// Mismo cálculo que el workflow de envío: los cumples de hoy son los que
// caen dentro de 10 días. Así el informe audita exactamente la misma lista.
const hoy = new Date();
const objetivo = new Date(hoy);
objetivo.setDate(hoy.getDate() + 10);

const p = (n) => String(n).padStart(2, '0');
const mmdd = p(objetivo.getMonth() + 1) + '-' + p(objetivo.getDate());
const iso  = hoy.getFullYear() + '-' + p(hoy.getMonth() + 1) + '-' + p(hoy.getDate());

return [{ json: {
  hoy_iso: iso,
  cumple_mmdd: mmdd,
  cumple_texto: p(objetivo.getDate()) + '/' + p(objetivo.getMonth() + 1),
  hoy_medianoche: Math.floor(new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate()).getTime() / 1000),
}}];

function normalizaTelefono(raw) {
  const original = String(raw ?? '').trim();
  if (!original) return { ok: false, motivo: 'sin teléfono en PrestaShop' };
  const teniaMas = original.startsWith('+');
  let s = original.replace(/\D/g, '');
  if (!s) return { ok: false, motivo: 'teléfono sin dígitos' };
  if (s.startsWith('00')) s = s.slice(2);
  else if (!teniaMas && s.length === 9) s = '34' + s;
  if (s.length < 8 || s.length > 15) return { ok: false, motivo: 'longitud no válida (' + s.length + ' dígitos)' };
  return { ok: true, e164: s };
}

const salida = [];
for (const item of $input.all()) {
  const c = (item.json && item.json.customer) || {};
  const bruto = c.phone_mobile || c.phone || '';
  const r = normalizaTelefono(bruto);
  salida.push({ json: {
    nombre:  String(c.firstname || '').trim(),
    apellidos: String(c.lastname || '').trim(),
    email:   c.email || '',
    telefono_bruto: bruto,
    telefono_e164:  r.ok ? r.e164 : '',
    telefono_ok:    r.ok,
    motivo_descarte: r.ok ? '' : r.motivo,
  }});
}
return salida;

// Día sin cumpleaños: la consulta no devolvió filas y el nodo emitió un item
// vacío. Se marca y "Construye el informe" lo descarta.
const fila = $('Por Cada Cumple').first().json;
if (!fila || !fila.id_customer) return [{ json: { __vacio: true } }];

const t0    = $('Fechas del informe').first().json.hoy_medianoche;
const hijo  = String(fila.value || '').trim();
const tel   = $('Normaliza Teléfono').first().json;
const msgs  = ($input.first().json || {}).payload || [];

const AUTO = /RESPUESTA\s*AUTOM|𝑹𝑬𝑺𝑷𝑼𝑬𝑺𝑻𝑨/i;

// El envío de hoy: mensaje saliente público creado hoy que menciona al niño.
// Una nota privada NO cuenta como envío.
const envio = msgs.filter(m =>
  m.message_type === 1 && !m.private && m.created_at >= t0 &&
  String(m.content || '').includes('Se acerca el cumple de')
).sort((a, b) => b.created_at - a.created_at)[0];

const ESTADO = { read: 'Leído', delivered: 'Entregado', sent: 'Enviado', failed: 'FALLIDO' };

let estado, lectura, respuesta;
if (!tel.telefono_ok || !envio) {
  estado = 'NO ENVIADO'; lectura = '—'; respuesta = '—';
} else {
  estado  = envio.status === 'failed' ? 'FALLIDO' : 'Enviado';
  lectura = ESTADO[envio.status] || envio.status || 'Enviado';
  const posteriores = msgs.filter(m => m.message_type === 0 && m.created_at > envio.created_at);
  const reales = posteriores.filter(m => !AUTO.test(String(m.content || '')));
  respuesta = reales.length ? 'Sí (' + reales.length + ')'
            : (posteriores.length ? 'Solo autorespuesta' : 'No');
}

return [{ json: {
  cliente: (tel.nombre + ' ' + tel.apellidos).trim() || '(sin nombre)',
  hijo,
  telefono: tel.telefono_ok ? '+' + tel.telefono_e164 : (tel.telefono_bruto || '—'),
  estado, lectura, respuesta,
  incidencia: !tel.telefono_ok ? tel.motivo_descarte
            : (!envio ? 'no se encontró el mensaje de hoy en Chatwoot' : ''),
}}];

const f = $('Fechas del informe').first().json;
// ⚠️ CAMBIAR: remitente verificado en Resend (tiene que ser de tu dominio).
const REMITENTE = 'El Rincón de los Genios <informes@__TU_DOMINIO__>';
const DESTINO   = 'elrincondelosgenios31@gmail.com';

const filas = $input.all().map(i => i.json)
  .filter(r => !r.__vacio)
  .sort((a, b) => a.cliente.localeCompare(b.cliente));

const total      = filas.length;
const enviados   = filas.filter(r => r.estado === 'Enviado').length;
const fallidos   = filas.filter(r => r.estado === 'FALLIDO').length;
const noEnviados = filas.filter(r => r.estado === 'NO ENVIADO').length;
const leidos     = filas.filter(r => r.lectura === 'Leído').length;
const contestan  = filas.filter(r => String(r.respuesta).startsWith('Sí')).length;

const esc = (s) => String(s ?? '').replace(/[&<>]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
const color = (r) => r.estado === 'Enviado' ? '#1a7f37' : (r.estado === 'FALLIDO' ? '#b42318' : '#a15c00');

const filasHtml = filas.map(r => `
      <tr>
        <td style="padding:8px 10px;border-bottom:1px solid #eee">${esc(r.cliente)}</td>
        <td style="padding:8px 10px;border-bottom:1px solid #eee">${esc(r.hijo)}</td>
        <td style="padding:8px 10px;border-bottom:1px solid #eee;white-space:nowrap">${esc(r.telefono)}</td>
        <td style="padding:8px 10px;border-bottom:1px solid #eee;color:${color(r)};font-weight:600">${esc(r.estado)}</td>
        <td style="padding:8px 10px;border-bottom:1px solid #eee">${esc(r.lectura)}</td>
        <td style="padding:8px 10px;border-bottom:1px solid #eee">${esc(r.respuesta)}</td>
        <td style="padding:8px 10px;border-bottom:1px solid #eee;color:#a15c00;font-size:12px">${esc(r.incidencia)}</td>
      </tr>`).join('');

const tarjeta = (n, t) => `<td style="padding:12px 16px;background:#f6f8fa;border-radius:8px;text-align:center">
        <div style="font-size:24px;font-weight:700;color:#111">${n}</div>
        <div style="font-size:12px;color:#555">${t}</div></td>`;

const html = `<!doctype html><html><body style="margin:0;padding:24px;background:#fff;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111">
  <h2 style="margin:0 0 4px">Felicitaciones de cumpleaños — ${esc(f.hoy_iso)}</h2>
  <p style="margin:0 0 20px;color:#555;font-size:14px">Cumpleaños del ${esc(f.cumple_texto)} (dentro de 10 días).</p>
  <table style="border-collapse:separate;border-spacing:8px 0;margin-bottom:20px"><tr>
    ${tarjeta(total, 'cumples')}${tarjeta(enviados, 'enviados')}${tarjeta(leidos, 'leídos')}${tarjeta(contestan, 'han contestado')}${tarjeta(fallidos + noEnviados, 'sin enviar')}
  </tr></table>
  ${total === 0 ? '<p style="color:#555">Hoy no había ningún cumpleaños que felicitar.</p>' : `
  <table style="border-collapse:collapse;width:100%;font-size:14px">
    <thead><tr style="background:#f6f8fa;text-align:left">
      <th style="padding:8px 10px">Clienta</th><th style="padding:8px 10px">Peque</th>
      <th style="padding:8px 10px">Teléfono</th><th style="padding:8px 10px">Envío</th>
      <th style="padding:8px 10px">Estado</th><th style="padding:8px 10px">¿Ha contestado?</th>
      <th style="padding:8px 10px">Incidencia</th>
    </tr></thead><tbody>${filasHtml}</tbody></table>`}
  <p style="margin-top:24px;color:#888;font-size:12px">Informe automático de n8n · El Rincón de los Genios</p>
</body></html>`;

const pl = (n, s, p) => n + ' ' + (n === 1 ? s : p);
const asunto = `Cumpleaños ${f.hoy_iso} — ${pl(enviados, 'enviado', 'enviados')}, ` +
               `${pl(leidos, 'leído', 'leídos')}, ${pl(contestan, 'respuesta', 'respuestas')}` +
               ((fallidos + noEnviados) ? ` · ${fallidos + noEnviados} SIN ENVIAR` : '');

return [{ json: {
  asunto, html, destino: DESTINO,
  total, enviados, leidos, contestan, fallidos, noEnviados,
  resend_body: { from: REMITENTE, to: [DESTINO], subject: asunto, html },
} }];
